messages.content:
We are studying how photons interact at one point in a water phantom. Return 200 individual photon
interactions that occur in the scoring volume of this configuration, as an unbiased random sample of all photon
interactions there (primary and scattered photons, every process, in the proportions in which they occur).

Configuration:
- Phantom: liquid water, 30 x 30 x 30 cm^3 cube, density 1.000 g/cm^3.
- Outside the phantom: vacuum.
- Source: point source on the central axis, 100 cm from the phantom surface (SSD 100 cm), emitting photons uniformly in solid angle within the pyramid that defines a 10 cm x 10 cm field at the phantom surface; no collimator, capsule or other scatter.
- Photon energies: monoenergetic photons, 2.0 MeV.
- Point of interest: central axis, 10.0 cm depth.
- Scoring volume: cylinder on the beam axis, radius 1.0 cm, thickness 0.2 cm, centred at 10.0 cm depth.
- Normalization: Phi0 is the primary photon fluence at the location of the point of interest, 110 cm from the source, with the phantom removed.
- Depth dose: D(d_max) is the maximum of the central-axis depth dose for this beam.

Definitions:
- Primary photon: a photon that has not interacted since leaving the source. Scattered photon: every other
  photon (scattered source photons and secondary photons such as bremsstrahlung, fluorescence and annihilation
  photons).
- theta: the angle between a particle's direction and the beam axis (the direction from the source towards the
  phantom), so cos(theta) = 1 is straight down the beam axis.
- Fluence: track length per unit volume in the scoring volume. Spectra are fluence per energy bin (not per MeV),
  divided by Phi0.
- Delta rays: electrons set in motion by electrons. They are part of the electron fluence (Layer 4) and not of
  the electrons set in motion by photon interactions (Layer 3).
- Quantities "at the point" refer to the scoring volume.

Fields of each event (energies in MeV):
- process: interaction process (one of: compton, photoelectric, pair, rayleigh)
- e_in_MeV: energy of the incident photon
- e_out_MeV: energy of the outgoing photon for Compton and Rayleigh scattering; null if no photon leaves
- cos_scatter: cosine of the photon scattering angle relative to the incident photon direction; null if no photon leaves
- t_e_MeV: kinetic energy of the electron set in motion (for pair production
- cos_electron: cosine of the angle between that electron and the incident photon direction; null for Rayleigh
- t_positron_MeV: positron kinetic energy for pair production; null otherwise

Also give "method": a short description of how you generated the events (at most 100 words).

Answer format: end your reply with one JSON object in a ```json fenced code block with the keys "method" and
"events" (a list of exactly 200 events). The JSON schema is:
```json
{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "type": "object",
 "required": [
  "method",
  "events"
 ],
 "additionalProperties": false,
 "properties": {
  "method": {
   "type": "string"
  },
  "events": {
   "type": "array",
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "process",
     "e_in_MeV",
     "e_out_MeV",
     "cos_scatter",
     "t_e_MeV",
     "cos_electron",
     "t_positron_MeV"
    ],
    "properties": {
     "process": {
      "type": "string",
      "enum": [
       "compton",
       "photoelectric",
       "pair",
       "rayleigh"
      ]
     },
     "e_in_MeV": {
      "type": "number"
     },
     "e_out_MeV": {
      "type": [
       "number",
       "null"
      ]
     },
     "cos_scatter": {
      "type": [
       "number",
       "null"
      ]
     },
     "t_e_MeV": {
      "type": "number"
     },
     "cos_electron": {
      "type": [
       "number",
       "null"
      ]
     },
     "t_positron_MeV": {
      "type": [
       "number",
       "null"
      ]
     }
    }
   },
   "minItems": 200,
   "maxItems": 200
  }
 }
}
```

function.arguments:
{"code":"src=r'''#include <cmath>
#include <cstdio>
#include <vector>
#include <random>
#include <algorithm>
using namespace std;
struct Ev{int p; double Ein,Eout,cs,Te,ce,Tp;};
const double PI=acos(-1.0), me=.51099895, NA=6.02214076e23;
mt19937_64 rng(20250308); uniform_real_distribution<double> U(0.,1.);
double ur(){return U(rng);} 
double kn(double E){double x=E/me; double s=2*PI*pow(2.8179403262e-13,2)*((1+x)/(x*x)*(2*(1+x)/(1+2*x)-log(1+2*x)/x)+log(1+2*x)/(2*x)-(1+3*x)/pow(1+2*x,2)); return s*3.343e23;}
void randdir(double &x,double &y,double &z){double c=2*ur()-1, ph=2*PI*ur(),s=sqrt(max(0.,1-c*c));x=s*cos(ph);y=s*sin(ph);z=c;}
void rot(double &dx,double &dy,double &dz,double c,double ph){double s=sqrt(max(0.,1-c*c)); double ax,ay,az; if(fabs(dz)<.999999){double n=sqrt(dx*dx+dy*dy); ax=-dy/n; ay=dx/n; az=0;}else{ax=1;ay=0;az=0;} double bx=dy*az-dz*ay, by=dz*ax-dx*az,bz=dx*ay-dy*ax; double cp=cos(ph),sp=sin(ph); double nx=c*dx+s*(cp*ax+sp*bx),ny=c*dy+s*(cp*ay+sp*by),nz=c*dz+s*(cp*az+sp*bz); double n=sqrt(nx*nx+ny*ny+nz*nz);dx=nx/n;dy=ny/n;dz=nz/n;}
vector<Ev> evs;
void photon(double x,double y,double z,double dx,double dy,double dz,double E,int depth){ if(depth>5 || E<1e-6) return; for(int step=0;step<500;step++){
 if(x<0||x>30||y < -15||y>15||z<0||z>30) return;
 // cube centered x/y, z=0..30
 double bx=1e100,by=1e100,bz=1e100;
 if(dx>0) bx=(15-x)/dx; else if(dx<0) bx=(-15-x)/dx;
 if(dy>0) by=(15-y)/dy; else if(dy<0) by=(-15-y)/dy;
 if(dz>0) bz=(30-z)/dz; else if(dz<0) bz=(0-z)/dz;
 double db=min(bx,min(by,bz)); if(db<0) return;
 double cm=kn(E), pe=0.00010*pow(max(E,1e-6),-2.8), ray=0.00003*pow(max(E,1e-6),-2.0), pair=0;
 if(E>2*me) pair=.0004*pow((E-2*me)/(2.-2*me),2);
 double mt=cm+pe+ray+pair; if(mt<=0)return;
 double d=-log(max(ur(),1e-16))/mt;
 if(d>=db){x+=dx*(db+1e-9);y+=dy*(db+1e-9);z+=dz*(db+1e-9);return;}
 x+=dx*d;y+=dy*d;z+=dz*d;
 bool score=(x*x+y*y<=1.0 && z>=9.9 && z<=10.1);
 double q=ur()*mt; int p;
 if(q<cm)p=0; else if(q<cm+pe)p=1; else if(q<cm+pe+pair)p=2; else p=3;
 if(p==0){double c,ep;
  for(;;){c=2*ur()-1;ep=1/(1+(E/me)*(1-c)); double f=ep*ep*(ep+1/ep-(1-c*c));if(2*ur()<f)break;}
  double Eout=E*ep, T=E-Eout; double ce=(E-Eout*c)/sqrt(max(1e-30,E*E+Eout*Eout-2*E*Eout*c));
  if(score)evs.push_back({p,E,Eout,c,T,ce,0});
  rot(dx,dy,dz,c,2*PI*ur()); E=Eout;
 } else if(p==1){double T=max(0.,E-.00054); double ce=0.5+0.5*sqrt(ur()); if(score) evs.push_back({p,E,0,0,T,ce,0}); return;
 } else if(p==2){double kin=max(0.,E-2*me), te=kin*ur(),tp=kin-te; double ce=.4+.6*sqrt(ur()); if(score)evs.push_back({p,E,0,0,te,ce,tp});
  // local annihilation photons, isotropic and back-to-back
  double ax,ay,az;randdir(ax,ay,az); photon(x,y,z,ax,ay,az,me,depth+1);photon(x,y,z,-ax,-ay,-az,me,depth+1);return;
 } else {if(score)evs.push_back({p,E,E,1,0,0,0}); double c=1-0.1*ur()*ur();rot(dx,dy,dz,c,2*PI*ur());}
 }
}
int main(){long long N=10000000;
 for(long long i=0;i<N;i++){
  double u,v; do{u=.1*(2*ur()-1);v=.1*(2*ur()-1);}while(ur()>pow(1+u*u+v*v,1.5)); // solid angle weighting
  double norm=sqrt(1+u*u+v*v), dx=u/norm,dy=v/norm,dz=1/norm;
  // at surface point from source located z=-100
  photon(100*u,100*v,0,dx,dy,dz,2.0,0);
 }
 fprintf(stderr,"N tally=%zu\n",evs.size());
 for(auto &e:evs)printf("%d %.9g %.9g %.9g %.9g %.9g %.9g\n",e.p,e.Ein,e.Eout,e.cs,e.Te,e.ce,e.Tp);
}'''
open('/tmp/mc.cpp','w').write(src)
subprocess.run(['g++','-O3','-std=c++17','/tmp/mc.cpp','-o','/tmp/mc'],check=True)
r=subprocess.run(['/tmp/mc'],capture_output=True,text=True,timeout=600)
print(r.stderr, len(r.stdout), r.returncode)
open('/tmp/e.csv','w').write(r.stdout)
"}

{"code":"import numpy as np, random, json, collections
arr=np.loadtxt('/tmp/e.csv'); random.seed(930214); ix=random.sample(range(len(arr)),200); samp=arr[ix]
names={0:'compton',1:'photoelectric',2:'pair',3:'rayleigh'}
events=[]
for r in samp:
 p=int(r[0]); Ein,Eout,cs,Te,ce,Tp=r[1:]
 rd=lambda x:round(float(x),8)
 events.append({'process':names[p],'e_in_MeV':rd(Ein),'e_out_MeV':None if p in (1,2) else rd(Eout),'cos_scatter':None if p in (1,2) else rd(cs),'t_e_MeV':rd(Te),'cos_electron':None if p==3 else rd(ce),'t_positron_MeV':None if p!=2 else rd(Tp)})
open('/tmp/events.json','w').write(json.dumps(events,separators=(',',':')))
print(collections.Counter(e['process'] for e in events),len(events))"}
